"""Auto-generated by ORIGIN (algobench domain). Self-contained experiment.

Design spec: see spec.json alongside this file. This file is versioned and
kept forever as part of the research history.

Emits result schema v2: per-trial samples, descriptive statistics, input and
output digests (so a replay can prove the inputs and results are identical,
not merely similar), the exact environment the measurements came from, and a
fixed reference micro-benchmark used to express host speed.
"""
import hashlib, json, platform, statistics, sys, time

CONFIG = {
    "kind": "replication",
    "round": 0,
    "algorithms": [
        "insertion_sort",
        "merge_sort",
        "quick_sort",
        "heap_sort",
        "shell_sort"
    ],
    "regimes": [
        "random",
        "nearly_sorted",
        "reversed",
        "few_unique"
    ],
    "sizes": [
        4096
    ],
    "trials": 7,
    "seed": 20261809,
    "timeout_s": 600,
    "hypothesis_ids": [
        "hyp_dbe5f386a7"
    ],
    "origin_version": "1.3.0"
}
RESULT_SCHEMA_VERSION = 2

# ---- embedded candidate algorithms -----------------------------------------
def gen_random(n, seed):
    import random
    r = random.Random(seed)
    return [r.randrange(n * 10) for _ in range(n)]


def gen_nearly_sorted(n, seed):
    import random
    r = random.Random(seed)
    a = list(range(n))
    for _ in range(max(1, n // 100)):
        i = r.randrange(n - 1)
        a[i], a[i + 1] = a[i + 1], a[i]
    return a


def gen_reversed(n, seed):
    return list(range(n, 0, -1))


def gen_few_unique(n, seed):
    import random
    r = random.Random(seed)
    return [r.randrange(8) for _ in range(n)]


def insertion_sort(a):
    a = list(a)
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a


def _merge(left, right):
    out = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            out.append(left[i]); i += 1
        else:
            out.append(right[j]); j += 1
    out.extend(left[i:])
    out.extend(right[j:])
    return out


def merge_sort(a):
    a = list(a)
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    return _merge(merge_sort(a[:mid]), merge_sort(a[mid:]))


def quick_sort(a):
    a = list(a)
    stack = [(0, len(a) - 1)]
    while stack:
        lo, hi = stack.pop()
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < a[lo]:
                a[lo], a[mid] = a[mid], a[lo]
            if a[hi] < a[lo]:
                a[lo], a[hi] = a[hi], a[lo]
            if a[hi] < a[mid]:
                a[mid], a[hi] = a[hi], a[mid]
            pivot = a[mid]
            i, j = lo - 1, hi + 1
            while True:
                i += 1
                while a[i] < pivot:
                    i += 1
                j -= 1
                while a[j] > pivot:
                    j -= 1
                if i >= j:
                    break
                a[i], a[j] = a[j], a[i]
            if j - lo < hi - (j + 1):
                stack.append((j + 1, hi))
                hi = j
            else:
                stack.append((lo, j))
                lo = j + 1
    return a


def heap_sort(a):
    a = list(a)
    n = len(a)

    def sift(start, end):
        root = start
        while 2 * root + 1 <= end:
            child = 2 * root + 1
            if child + 1 <= end and a[child] < a[child + 1]:
                child += 1
            if a[root] < a[child]:
                a[root], a[child] = a[child], a[root]
                root = child
            else:
                return

    for s in range(n // 2 - 1, -1, -1):
        sift(s, n - 1)
    for e in range(n - 1, 0, -1):
        a[0], a[e] = a[e], a[0]
        sift(0, e - 1)
    return a


def shell_sort(a):
    a = list(a)
    n = len(a)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            tmp = a[i]
            j = i
            while j >= gap and a[j - gap] > tmp:
                a[j] = a[j - gap]
                j -= gap
            a[j] = tmp
        gap //= 2
    return a


ALGORITHMS = {"insertion_sort": insertion_sort, "merge_sort": merge_sort, "quick_sort": quick_sort, "heap_sort": heap_sort, "shell_sort": shell_sort}
GENERATORS = {"random": gen_random, "nearly_sorted": gen_nearly_sorted, "reversed": gen_reversed, "few_unique": gen_few_unique}


def digest(seq):
    """Stable content digest of a sequence of numbers."""
    h = hashlib.sha256()
    for x in seq:
        h.update(repr(x).encode())
        h.update(b",")
    return h.hexdigest()[:16]


def file_digest(path):
    try:
        return hashlib.sha256(open(path, "rb").read()).hexdigest()[:16]
    except OSError:
        return ""


def reference_workload():
    """Fixed, deterministic micro-benchmark: lets a reader compare hosts.

    It is NOT part of any hypothesis; it exists so absolute timings from
    different machines can be put in proportion.
    """
    import random
    rnd = random.Random(987654321)
    data = [rnd.random() for _ in range(20000)]
    times = []
    for _ in range(5):
        copy = list(data)
        t0 = time.perf_counter()
        copy.sort()
        times.append(time.perf_counter() - t0)
    return statistics.median(times)


def environment():
    info = {
        "python_version": platform.python_version(),
        "python_implementation": platform.python_implementation(),
        "system": platform.system(),
        "release": platform.release(),
        "machine": platform.machine(),
        "processor": platform.processor(),
        "cpu_count": __import__("os").cpu_count(),
        "origin_version": CONFIG.get("origin_version", "unknown"),
        "timestamp_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "timer": "time.perf_counter",
        "timer_resolution_s": time.get_clock_info("perf_counter").resolution,
    }
    return info


def main():
    rows = []
    input_digests = {}
    for alg_name in CONFIG["algorithms"]:
        fn = ALGORITHMS[alg_name]
        for regime in CONFIG["regimes"]:
            gen = GENERATORS[regime]
            for n in CONFIG["sizes"]:
                times = []
                out_digest = ""
                for t in range(CONFIG["trials"]):
                    data = gen(n, CONFIG["seed"] + t)
                    expected = sorted(data)
                    if t == 0:
                        input_digests.setdefault((regime, n), digest(data))
                    t0 = time.perf_counter()
                    out = fn(data)
                    dt = time.perf_counter() - t0
                    if out != expected:
                        json.dump({"error": "INCORRECT OUTPUT: " + alg_name},
                                  open("result.json", "w"))
                        print("CORRECTNESS FAILURE:", alg_name)
                        sys.exit(2)
                    if t == 0:
                        out_digest = digest(out)
                    times.append(dt)
                stdev = statistics.stdev(times) if len(times) > 1 else 0.0
                rows.append({
                    "algorithm": alg_name, "regime": regime, "n": n,
                    "correct": True,
                    "trials": CONFIG["trials"],
                    "samples": times,
                    "mean_s": statistics.fmean(times),
                    "median_s": statistics.median(times),
                    "stdev_s": stdev,
                    "sem_s": stdev / (len(times) ** 0.5) if len(times) > 1 else 0.0,
                    "min_s": min(times),
                    "input_digest": input_digests[(regime, n)],
                    "output_digest": out_digest,
                })
    payload = {
        "schema_version": RESULT_SCHEMA_VERSION,
        "environment": environment(),
        "config": CONFIG,
        "code_digest": file_digest(__file__),
        "reference_workload_s": reference_workload(),
        "rows": rows,
    }
    with open("result.json", "w") as f:
        json.dump(payload, f, indent=2)
    print("OK", len(rows), "measurements")


main()
